{{groovy}}
import com.xpn.xwiki.api.PropertyClass;
import org.xwiki.velocity.tools.JSONTool;

JSONTool jsontool = new JSONTool();

if (request.editmetadataset == "1") {
    xwiki.jsx.use('MetadataPro.Code.MetadataSetInstanceSheet');
    xwiki.ssx.use('MetadataPro.Code.MetadataSetInstanceSheet');

    def metadataset = request.metadataset;
    if (metadataset) {
        def setDoc = xwiki.getDocument(metadataset)
        def setObj = setDoc.getObject("MetadataPro.Code.MetadataSetClass");
        if (setObj) {
            def requiredFields = setObj.getValue("requiredFields");
            def defaultValuesStr = setObj.getValue("defaultValues");
            def defaultValues = (defaultValuesStr == null || defaultValuesStr == "") ? [] : jsontool.fromString(defaultValuesStr);
            println "Editing data for set ${setDoc.getTitle()}:";
            def objIsNew = false;
            def obj = doc.getObject(metadataset);
            if (!obj) {
                objIsNew = true;
                obj = doc.getObject(metadataset, true);
                def objInputName = metadataset + "_" + obj.number;
                println "{{html clean=false}}<input type='hidden' name='addedObjects' value='" + services.xml.escape(objInputName) + "' />{{/html}}";
            }
            println "\n\n{{html clean=false}}<div class='xform'>{{/html}}\n"
            def xclass = obj.xWikiClass;
            for (PropertyClass property : xclass.properties) {
                def required = requiredFields.contains(property.name);
                if (objIsNew) {
                    def defVals = defaultValues.get(property.name);
                    if (defVals != null && !defVals.isEmpty()) {
                        obj.set(property.name, property.type == "StaticListClass" ? defVals : defVals[0]);
                    }
                }
                println "; " + property.prettyName + (required ? "{{html}}<span class='metadatapro-required'>*</span>{{/html}}" : "")
                println ": " + (required ? "{{html clean='false'}}<span class='metadatapro-required-field'>{{/html}}" : "") + doc.display(property.getName()) + (required ? "{{html clean='false'}}</span>{{/html}}" : "")
            }
            println "\n\n{{html clean=false}}</div>{{/html}}\n"
        } else {
            println services.localization.render("metadatapro.nosuchset")
        }
    } else {
        println services.localization.render("metadatapro.nosuchset")
    }
} else if (request.deletemetadataset == "1") {
    def metadataset = request.metadataset;
    def obj = null;
    if (metadataset) {
        def setDoc = xwiki.getDocument(metadataset)
        if (setDoc.getObject("MetadataPro.Code.MetadataSetClass")) {
            obj = doc.getObject(metadataset);
        }
    }

    if (obj) {
        def objInputName = metadataset + "_" + obj.number;
        println "{{html clean=false}}<input type='hidden' name='deletedObjects' value='" + services.xml.escape(objInputName) + "' />{{/html}}";
        println ""
        println "{{info}}"
        println services.localization.render("metadatapro.savetoconfirmdeletion")
        println "{{/info}}"
        println ""

    } else {
        println ""
        println "{{warning}}"
        println services.localization.render("metadatapro.nosuchset")
        println "{{/warning}}"
        println ""
    }
}

println "{{html clean=false}}<template id='warnmissingrequiredfields'>${services.localization.render('metadatapro.warnmissingrequiredfields')}</template>{{/html}}"
{{/groovy}}

property.code:
window.addEventListener("DOMContentLoaded", () => {
  "use strict";
  if (document.observe) {
    document.observe("xwiki:actions:beforeSave", e => {
      for (const requiredContainer of document.getElementsByClassName('metadatapro-required-field')) {
        let found = false;
        for (const filledInput of requiredContainer.querySelectorAll(":checked, input, textarea")) {
          if (filledInput.type === "radio" || filledInput.type == "checkbox") {
            if (filledInput.checked) {
              found = true;
              break;
            }
          } else if (filledInput.value !== "") {
            found = true;
            break;
          }
        }
        if (!found) {
          alert(document.getElementById("warnmissingrequiredfields").content.textContent);
          e.preventDefault();
          const firstInputOfRequiredContainer = requiredContainer.querySelector("input, select");
          if (firstInputOfRequiredContainer) {
            firstInputOfRequiredContainer.focus();
          }
          return;
        }
      }
    });
  }
})
